// 1. is_par ← (block_length == gen_length); init mode-specific state (cons counter or kl_hist + p_prev)
// 2. for each block, compute uniform num_xfer schedule for steps_per_block
// 3. for step=1..steps_per_block:
// 4.   p ← softmax(model(x).logits); $x_0 = \arg\max_v p$; $\mathrm{conf}=p_{x_0}$; $\mathrm{margin}=p_{(1)}-p_{(2)}$; score = conf · margin
// 5.   if is_par: cons ← cons+1 where x0==prev_pred else 1; stable = cons ≥ history_length
// 6.   else: kl_hist ← shift+append KL($p$ ∥ $p_{prev}$); stable = all(kl_hist < $\tau_{kl}$) once history filled
// 7.   ready = stable ∧ (conf > $\tau_c$) ∧ mask_idx
// 8.   if any ready: unmask all ready positions
// 9.   else: pick top-k masked by score (k from num_xfer)
// 10. assign $x_0$ at chosen positions

// 1. semi_ar = (num_blocks > 1); pick (conf_thresh, margin_thresh, weight schedule, ready_rule) by regime
// 2. for each block, compute num_xfer; track p_prev and kl_hist[history_length]
// 3. for step in steps_per_block:
// 4.   logits = model(x); if temperature>0 add Gumbel; p = softmax
// 5.   conf = $p_{(1)}$; margin = $p_{(1)}-p_{(2)}$; KL = $\sum p\log(p/p_{prev})$; stable = all(kl_hist < $\tau_{kl}$)
// 6.   step_ratio = (b·steps_per_block + step)/(num_blocks·steps_per_block)
// 7.   margin_w, conf_w linearly interpolated and renormalized; score = conf_w·conf + margin_w·margin
// 8.   ready = stable ∧ mask_idx ∧ ((conf>conf_thresh) AND/OR (margin>margin_thresh)) per ready_rule
// 9.   if any ready: unmask all ready; else top-k masked by score (k from num_xfer)
// 10. assign x0 and continue

// 1. is_parallel = (block_length == gen_length)
// 2. for each block, compute num_xfer; maintain p_prev and kl_hist
// 3. for step in steps_per_block:
// 4.   logits = model(x); p = softmax
// 5.   if temperature>0 OR is_parallel (with τ=0.1): x0 = argmax(log p + τ·Gumbel) else x0 = argmax p
// 6.   conf = $p_{(1)}$; margin = $p_{(1)}-p_{(2)}$; update KL stability over kl_hist
// 7.   ready = stable ∧ (conf > $\tau_c$) ∧ mask_idx
// 8.   for each row j:
// 9.     unmask all ready positions
// 10.    if is_parallel: ranking score = margin + 0.15·Gumbel; top up to (num_xfer - num_ready) more masked positions; else if num_ready==0 fall back to confidence top-k of size num_xfer
// 11.   if step == steps_per_block - 1: force-unmask all remaining masked positions in this block
// 12.   commit x ← x0 at xfer; update p_prev

// 1. for each block, compute num_xfer; reset p_prev, prev_x0, stable_run
// 2. for step in steps_per_block:
// 3.   logits = model(x); if temperature>0 logits/=T; p = softmax
// 4.   top2 → x0, conf, margin = $p_{(1)}-p_{(2)}$; KL($p$ ∥ $p_{prev}$)
// 5.   stable = KL < $\tau_{kl}$ ∧ x0 == prev_x0; stable_run += stable else reset
// 6.   progress = (step+1)/steps_per_block; relax conf/margin thresholds with progress
// 7.   ready = mask_idx ∧ conf>conf_gate ∧ ((stable_run≥history_length-1 ∧ margin_gate) ∨ very-conf ∨ very-margin)
// 8.   score = $\alpha(\text{progress})\,\mathrm{conf} + \beta(\text{progress})\,\mathrm{margin}$ + agree_bonus·agree + stable_bonus·run_gate (+parallel boost if fully parallel)
// 9.   adaptive k = max(num_xfer, ready_count, num_xfer + ready_count/2 [·parallel_boost]); top-k masked by score
// 10.  assign x0 at chosen positions; update prev_x0, p_prev

// 1. for each block, compute num_xfer; init $p_{ema} = 1/V$
// 2. for step in steps_per_block:
// 3.   logits = model(x); p = softmax; x0 = argmax p; conf = $p_{x_0}$; margin = $p_{(1)}-p_{(2)}$
// 4.   entropy $H = -\sum p \log p$, $\bar H = H/\log V$
// 5.   $\mathrm{decay} = \min(0.3 + 0.7\cdot \mathrm{step}/(S-1), 0.9)$; $p_{ema} \leftarrow \mathrm{decay}\,p_{ema} + (1-\mathrm{decay})\,p$
// 6.   $\mathrm{kl\_stab} = \sum p \log(p / p_{ema})$
// 7.   adapt $\tau_{c}^{\mathrm{eff}} = \tau_c \cdot (1 - 0.5\cdot \mathrm{step}/(S-1)) \cdot (1 - 0.3\cdot \min(\mathrm{frac\_masked}\,S/\mathrm{step\_budget}, 1))$
// 8.   ready = mask_idx ∧ conf > $\tau_c^{\mathrm{eff}}$ ∧ $\bar H < \tau_H$ ∧ kl_stab < $\tau_{kl}$ (no entropy/stability gate at step 0)
// 9.   if |ready| ≥ k = num_xfer: pick top-k of ready by conf
// 10.  elif |ready| > 0: take all ready, fill rest by hybrid score $0.4(1-\bar H) + 0.3\,\mathrm{conf} + 0.3\,\mathrm{margin} + 0.1\,(1 - \mathrm{clip}(kl\_stab))$
// 11.  else: top-k by hybrid score; assign x0 at chosen positions
